// 请假申请表单 - JS 增强代码

// 1. 表单修改回调：请假类型联动备注 + 日期时间变化自动计算天数
this.form.onValuesChange = (FieldsValue, changedValues) => {
  // 当请假类型变化时，自动在备注中填入提示
  if (changedValues.qingjialeixing) {
    const leixing = FieldsValue.qingjialeixing || '';

    if (leixing === '病假') {
      // 病假时自动在备注中填入"需提供病假证明"
      this.form.setFieldsValue({
        beizhu: '需提供病假证明'
      });
    } else {
      // 其他类型清空备注
      this.form.setFieldsValue({
        beizhu: ''
      });
    }
  }

  // 当开始时间或结束时间变化时，自动计算请假天数
  if (changedValues.kaishishijian || changedValues.jieshushijian) {
    const startTime = FieldsValue.kaishishijian;
    const endTime = FieldsValue.jieshushijian;

    if (startTime && endTime) {
      // 使用 dayjs 计算小时差
      const start = _tool.dayjs(startTime);
      const end = _tool.dayjs(endTime);

      // 计算相差小时数
      const hoursDiff = end.diff(start, 'hour');

      // 转换为天数，精确到 0.5 天
      // 不足 12 小时按 0.5 天计算，超过 12 小时不足 24 小时按 1 天计算
      let days = 0;
      if (hoursDiff > 0) {
        days = Math.ceil(hoursDiff / 12) * 0.5;
        // 保留一位小数
        days = Math.round(days * 10) / 10;
      }

      // 回填到请假天数字段
      if (days > 0) {
        this.form.setFieldsValue({
          qingjiatushu: days
        });
      }
    } else {
      // 时间不完整时清空天数
      this.form.setFieldsValue({
        qingjiatushu: ''
      });
    }
  }

  return FieldsValue;
};

// 2. 保存前校验：结束时间不能早于开始时间
this.form.saveFormAgo = () => {
  const formData = this.form.getFieldsValue(true);
  const startTime = formData.kaishishijian;
  const endTime = formData.jieshushijian;

  // 校验开始时间和结束时间是否已填写
  if (!startTime) {
    _tool.Global.prompt('error', '请选择开始时间');
    return false;
  }

  if (!endTime) {
    _tool.Global.prompt('error', '请选择结束时间');
    return false;
  }

  // 校验结束时间不能早于开始时间
  const start = _tool.dayjs(startTime);
  const end = _tool.dayjs(endTime);

  if (end.isBefore(start)) {
    _tool.Global.prompt('error', '结束时间不能早于开始时间，请重新选择');
    return false;
  }

  return true;
};
